-- PerpScope V2 isolated strategy schema. Existing V1 tables/history remain unchanged.
CREATE TABLE IF NOT EXISTS public.v2_scan_runs (id uuid primary key default gen_random_uuid(),started_at timestamptz not null default now(),completed_at timestamptz,status text not null default 'running' check(status in('running','completed','failed')),symbols_scanned integer not null default 0,detailed_analyses integer not null default 0,signals_generated integer not null default 0,error_message text,metadata jsonb not null default '{}'::jsonb);
CREATE TABLE IF NOT EXISTS public.v2_trade_candidates (id bigint generated by default as identity primary key,scan_id uuid not null references public.v2_scan_runs(id) on delete cascade,symbol text not null,side text not null check(side in('LONG','SHORT','WATCH','REJECT')),score numeric not null default 0 check(score between 0 and 100),confidence_label text,entry_price numeric,stop_loss numeric,take_profit numeric,risk_reward numeric,risk_pct numeric not null default 1.0 check(risk_pct=1.0),risk_distance_pct numeric,reasons jsonb not null default '[]'::jsonb,filters jsonb not null default '{}'::jsonb,validation_status text not null default 'WATCH_ONLY',created_at timestamptz not null default now(),unique(scan_id,symbol),check(risk_reward is null or risk_reward=3.0));
CREATE TABLE IF NOT EXISTS public.v2_paper_trades (id uuid primary key default gen_random_uuid(),source_candidate_id bigint not null unique references public.v2_trade_candidates(id),scan_id uuid not null references public.v2_scan_runs(id),symbol text not null,side text not null check(side in('LONG','SHORT')),score numeric not null,confidence_label text,entry_price numeric not null,stop_loss numeric not null,take_profit numeric not null,risk_reward numeric not null default 3.0 check(risk_reward=3.0),risk_pct numeric not null default 1.0 check(risk_pct=1.0),signal_created_at timestamptz not null default now(),last_checked_at timestamptz not null default now(),status text not null default 'OPEN' check(status in('OPEN','WIN','LOSS')),exit_price numeric,exit_at timestamptz,exit_reason text,realized_r numeric,realized_pct numeric,duration_seconds bigint,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS public.v2_backtest_runs (id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),completed_at timestamptz,status text not null default 'running' check(status in('running','completed','failed')),strategy_version text not null default 'V2-CANDLE-PROXY',symbols text[] not null default '{}',interval text not null default '15m',start_time timestamptz not null,end_time timestamptz not null,initial_equity numeric,risk_pct numeric not null default 1.0 check(risk_pct=1.0),total_trades integer not null default 0,wins integer not null default 0,losses integer not null default 0,win_rate numeric,net_realized_r numeric,expectancy_r numeric,profit_factor numeric,max_drawdown_pct numeric,data_coverage jsonb not null default '{}'::jsonb,notes text,error_message text);
CREATE TABLE IF NOT EXISTS public.v2_backtest_trades (id bigint generated by default as identity primary key,backtest_id uuid not null references public.v2_backtest_runs(id) on delete cascade,symbol text not null,side text not null check(side in('LONG','SHORT')),entry_time timestamptz not null,exit_time timestamptz,entry_price numeric not null,stop_loss numeric not null,take_profit numeric not null,exit_price numeric,status text not null check(status in('OPEN','WIN','LOSS','NO_EXIT')),exit_reason text,risk_reward numeric not null default 3.0,realized_r numeric,risk_pct numeric not null default 1.0,filters jsonb not null default '{}'::jsonb);
CREATE INDEX IF NOT EXISTS idx_v2_candidates_created ON public.v2_trade_candidates(created_at desc);
CREATE INDEX IF NOT EXISTS idx_v2_candidates_scan ON public.v2_trade_candidates(scan_id);
CREATE INDEX IF NOT EXISTS idx_v2_paper_status_time ON public.v2_paper_trades(status,last_checked_at);
CREATE INDEX IF NOT EXISTS idx_v2_paper_symbol ON public.v2_paper_trades(symbol,signal_created_at);
CREATE INDEX IF NOT EXISTS idx_v2_backtest_trades_run ON public.v2_backtest_trades(backtest_id,entry_time);
ALTER TABLE public.v2_scan_runs ENABLE ROW LEVEL SECURITY; ALTER TABLE public.v2_trade_candidates ENABLE ROW LEVEL SECURITY; ALTER TABLE public.v2_paper_trades ENABLE ROW LEVEL SECURITY; ALTER TABLE public.v2_backtest_runs ENABLE ROW LEVEL SECURITY; ALTER TABLE public.v2_backtest_trades ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public read V2 scan runs" ON public.v2_scan_runs FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "Public read V2 candidates" ON public.v2_trade_candidates FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "Public read V2 paper trades" ON public.v2_paper_trades FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "Public read V2 backtest runs" ON public.v2_backtest_runs FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "Public read V2 backtest trades" ON public.v2_backtest_trades FOR SELECT TO anon,authenticated USING(true);
REVOKE INSERT,UPDATE,DELETE ON public.v2_scan_runs,public.v2_trade_candidates,public.v2_paper_trades,public.v2_backtest_runs,public.v2_backtest_trades FROM anon,authenticated;
GRANT SELECT ON public.v2_scan_runs,public.v2_trade_candidates,public.v2_paper_trades,public.v2_backtest_runs,public.v2_backtest_trades TO anon,authenticated;
GRANT ALL ON public.v2_scan_runs,public.v2_trade_candidates,public.v2_paper_trades,public.v2_backtest_runs,public.v2_backtest_trades TO service_role;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA public TO service_role;
CREATE OR REPLACE VIEW public.v2_paper_performance_summary WITH(security_invoker=true) AS SELECT count(*)::integer total_trades,count(*) FILTER(WHERE status='OPEN')::integer open_trades,count(*) FILTER(WHERE status IN('WIN','LOSS'))::integer completed_trades,count(*) FILTER(WHERE status='WIN')::integer wins,count(*) FILTER(WHERE status='LOSS')::integer losses,coalesce(sum(realized_r) FILTER(WHERE status IN('WIN','LOSS')),0) net_realized_r,CASE WHEN count(*) FILTER(WHERE status IN('WIN','LOSS'))>0 THEN round(100.0*count(*) FILTER(WHERE status='WIN')/count(*) FILTER(WHERE status IN('WIN','LOSS')),2) ELSE 0 END win_rate,CASE WHEN count(*) FILTER(WHERE status='WIN')>0 AND abs(coalesce(sum(realized_r) FILTER(WHERE status='LOSS'),0))>0 THEN abs(sum(realized_r) FILTER(WHERE status='WIN')/sum(realized_r) FILTER(WHERE status='LOSS')) ELSE null END profit_factor,coalesce(avg(realized_r) FILTER(WHERE status IN('WIN','LOSS')),0) expectancy_r FROM public.v2_paper_trades;
GRANT SELECT ON public.v2_paper_performance_summary TO anon,authenticated;